/// Find the last (rightmost, deepest) descendant node in a tree.
fn last_descendant(node: Node) -> Option<Node> {
    let child_count = node.child_count();
    if child_count == 0 {
        return Some(node);
    }
    let last_child = node.child(child_count - 1)?;
    last_descendant(last_child)
}

